<template>
    <section>
        <loader :is-visible="isLoading"></loader>
       
            <tg-list :showCheckBox="false" :IsShowAction="false" :listType="['List']" ModuleName="Asset"
                SubModuleCode="Asset" :PageSize="PageSize" IdentityColumn="CATALOGUE_ID"
                :HeaderText="$t('Approved Request')" :HeaderButtons="listheaderbuttons" :widgets="widgets" :ListData="ApprovedRequestData"
                :HeaderData="Headers" :callbackfunction="FetchData" :LegendArray="LegendArray"
                :SearchFields="leftSearchFields" v-on:LeftsearchButtonClick="leftCommonSearch" :SortExp="SortExp" :SortBy="SortBy"
                :NorecordfoundText="$t('NorecordfoundText')" :TotalRecords="TotalRecords"
                :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchData"
                v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
                v-on:SortdataButtonClick="sortdata">
                <template v-slot:slotdata="{ data }">

                    <template v-if="data.column.COLUMN_NAME == 'NUMBER_OF_ITEMS'">
                        <span class="text-dark" :title="data.column.COLUMN_NAME">
                            <i class="fa fa-list-ul" aria-hidden="true"></i><span class="noti-circle noti-green">{{
                                data.row.NUMBER_OF_ITEMS }}</span>
                        </span>
                    </template>

                    <template v-if="data.column.COLUMN_NAME == 'Assign'">

                        <span class="text-dark center-icon" title="Assign">
                            <a class="btn btn-success" title="Assign" @click="assign(data.row)">Assign</a>

                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'Comment'">
                                        <td class="text-center single-action">
                                            <span class="text-dark" title="Comments">
                                                <a href="javascript:;" id="comment" data-original-title="Comments"
                                                    @click="OpenComment(data.row)">
                                                    <em class="fa fa-eye text-info"></em>
                                                </a>
                                            </span>
                                        </td>
                                    </template>

                    <template v-if="data.column.COLUMN_NAME == 'approve_date'">
                            <span class="text-dark text-center" :title="data.column.COLUMN_NAME">
                                        {{ $options.filters.formatDateTimeMMDDYYY(data.row.approve_date) }}
                                      
                            </span>
                     </template>
                </template>
            </tg-list>
            <AssignApprovedProduct v-if="IsAssign" :ApprovedData="ApprovedData" @ClosePopUp="Closepop" @RefreshData="FetchData"></AssignApprovedProduct>
            <Comment v-if="isShowComment" :AssetAssignmentId="AssetAssignmentId" :ReplaceData="ApprovedData" :reqFrom="'approvedlist'"></Comment>
    </section>
</template>
<script>
import DataService from '../../service/DataService';
import AssignApprovedProduct from'../../components/Modal/AssignApprovedProduct.vue';
import Comment from'../../components/Modal/Comment.vue';
export default {
    components: { AssignApprovedProduct ,Comment},
    data() {
        return {
            listheaderbuttons:[],
            isLoading: false,
            widgets: [],
            Header: [],
            ApprovedRequestData: [],
            PageSize: 10,
            PageNumber: 1,
            TotalRecords: 0,
            SortExp: '',
            SortBy: '',
            LegendArray: [],
            leftSearchFields: [
                {  fieldName: "USER NAME", fieldType: "text", fieldIcon: "fa-user",paramName:"uName", fieldSearchConditionName: [''], isSearch: false,
                    value: "", listOptions: [] },
            ],
            Headers: [{
                "COLUMN_NAME": "ISSNUE_TO_NAME",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("IssueTo"),
                "DISPLAY_ORDER": 1,

            },
            {
                "COLUMN_NAME": "NAME",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("Product"),
                "DISPLAY_ORDER": 2
            },
            {
                "COLUMN_NAME": "UNIQUE_NAME",
                "DATA_TYPE": "text",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("product_unique_id"),
                "DISPLAY_ORDER": 3
            },
            {
                "COLUMN_NAME": 'NUMBER_OF_ITEMS',
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Quantity",
                "DISPLAY_ORDER": 4,
                settings: {
                    isInSlot: true,
                }

            },
            {
                "COLUMN_NAME": "REPLACEMENT_TYPE_STATUS",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("ProductConditions"),
                "DISPLAY_ORDER": 5
            },
            {
                "COLUMN_NAME": "APPROVER_NAME",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("ApproverName"),
                "DISPLAY_ORDER": 6
            },
            {
                "COLUMN_NAME": "approve_date",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("ApproveDate"),
                "DISPLAY_ORDER": 7,
                settings: {
                    isInSlot: true
                }
            },
            {
                "COLUMN_NAME": "Assign",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("Assign"),
                "DISPLAY_ORDER": 8,
                settings: {
                    isInSlot: true
                }
            },
            {
                "COLUMN_NAME": "Comment",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t("Comment"),
                "DISPLAY_ORDER": 9,
                settings: {
                    isInSlot: true
                }
            },
            ],
            IsAssign:false,
            ApprovedData:[],
            isShowComment:false,
            AssetAssignmentId:0
        }
    },
    created: async function () {
        await this.GetPageSize();
        this.FetchData();
    },
    methods: {
        FetchData() {
            this.isLoading = true;
            var url = `sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&${this.searchCondition}`;
            DataService.GetApprovedRequestList(url).then(response => {
                if (response.data != null && response.data != '' ) {
                    if (response.data.data.length > 0) {
                        console.log(response.data.data);
                        this.ApprovedRequestData = response.data.data;
                        this.TotalRecords = response.data.data[0].TOTAL_PAGES;
                        this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                        this.CurrentPages = this.PageNumber;
                        this.noRecord = false;
                        this.isLoading = false;
                    }
                    else {
                        this.noRecord = true;
                        this.ApprovedRequestData = [];
                        this.TotalRecords = 0
                        this.isLoading = false;
                    }
                }
                else {
                    this.noRecord = true;
                    this.ApprovedRequestData = [];
                    this.TotalRecord = 0
                    this.isLoading = false;
                }
            });
        },
        leftCommonSearch: function (value) {
            this.PageNumber = value.PageNumber;
            this.isPaged = 1;
            if (typeof value.searchCondition != 'undefined') {
                this.searchCondition = value.searchConditionJson;
            } else {
                this.searchCondition = "";
            }
            this.FetchData();
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        assign(row){
            this.ApprovedData=row;
            this.IsAssign=true;
        },
        Closepop(){
            this.IsAssign=false;
        },
        OpenComment(item){
            this.AssetAssignmentId = item.ASSET_ASSIGNMENT_ID;
            this.ApprovedData = item;
            this.isShowComment = true;

        },
        commonHeaderButtonClick: function () { },
        renderActions() { },
        renderRowActionMethod() { },
    }
}
</script>

<style>
    @media (max-width:767px){
        .collapse-head-btns {
            display: none !important;
        }
        .p-actions-expand:before{
            display: none;
        }
    }
</style>