<template>

    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t('AssignItem') }}
                        </h5>
                        <button v-on:click="ClosePOP($event)" type="button" class="close"
                            data-original-title="Close"><em class="fa fa-times"></em></button>
                    </div>
                    <div class="modal-body">
                        <div class="row">
                            <Form ref="product" class="product-type col-12 p-0" v-slot="{ valid, errors }">
                                <div class="col-md-12">
                                    <div class="row">
                                        <div class="col-md-6">
                                            <label> {{ $t('Old product serial number') }}:
                                                <!--  <span
                                                class="text-danger">*</span>-->
                                            </label>
                                            <div style="align-items: flex-start;">
                                                <Field name="Products" :rules="{ 'required': false }" label="ItemName"
                                                    v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="name" type="text"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="oldserialNumber" disabled="disabled" />

                                                    </div>
                                                    <span v-if="errors[0]" name="Serial Name"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>

                                            </div>
                                        </div>
                                        <div class="col-md-6">
                                            <label> {{ $t('Condition of old product') }}:</label>
                                            <div style="align-items: flex-start;">
                                                <Field name="Products" :rules="{ 'required': false }" label="ItemName"
                                                    v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="name" type="text"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="replacementStatusName" disabled="disabled" />

                                                    </div>
                                                </Field>

                                            </div>
                                        </div>

                                    </div>
                                    <div class="row">
                                        <div class="col-md-6">
                                            <div class="form-group">
                                                <label>{{ $t('ProductType') }}:</label>
                                                <Field name="Product Type" :rules="{ 'required': false }"
                                                    v-slot="{ errors }">
                                                    <select name="Product Type" v-model="txtProductType"
                                                        v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                        disabled="disabled">
                                                        <option value="">{{ $t('Select') }}
                                                        </option>
                                                        <option v-for="(item, itemIndex) in productTypeList"
                                                            :key="itemIndex" :value="item.ASSETID">{{ item.ASSETTYPE }}
                                                        </option>
                                                    </select>

                                                    <span v-if="errors[0]" name="Product Type"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>
                                            </div>
                                        </div>
                                        <div class="col-md-6">
                                            <label> {{ $t('UniqueName') }}:<span class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="Products" :rules="{ 'required': true }" label="ItemName"
                                                    v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="Products" id="Products" type="text"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="preUniqueName" disabled="disabled" />
                                                    </div>
                                                </Field>
                                            </div>
                                        </div>

                                        <div class="col-md-6">
                                            <label>{{ $t('Aproved Quantity') }}:<span
                                                    class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="AproveQuantity" :rules="{ 'required': false }"
                                                    label="ItemName" v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="receiptName" type="number"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="aproveQuantity" disabled="disabled" />

                                                    </div>
                                                    <span v-if="errors[0]" name="ApprovedQuantity"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>

                                            </div>
                                        </div>
                                        <div class="col-md-6">
                                            <label>{{ $t('RecipientName') }}:<span class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="RecipientName" :rules="{ 'required': true }"
                                                    label="ItemName" v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="receiptName" type="text"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="receiptName" disabled="disabled" />

                                                    </div>
                                                    <span v-if="errors[0]" name="RecipientName"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>

                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div class="col-md-12 mt-4">
                                    <div class="heading-border mt-2">
                                        <h5 class="h5"><span>{{ $t('Assign New or Refurbished Product ') }}</span>
                                            <small class="float-right">
                                            </small>
                                        </h5>
                                    </div>
                                </div>
                                <div class="col-md-12 mt-2">
                                    <div class="row">
                                        <div class="col-md-6">
                                            <div class="form-group">
                                                <div class="form-group">
                                                    <label>{{ $t('ProductName') }}:<span class="text-danger">*</span></label>
                                                    <Field name="ProductName" class="w-100" as="select"
                                                        :rules="{ 'required': true }" v-slot="{ errors }">
                                                        <select name="Product Name" v-model="txtProductName"
                                                            v-bind:class="{ 'form-control w-100': true, 'is-invalid': errors[0] }"
                                                            @change="searchByProduct(txtProductName)">
                                                            <option value="0">{{ $t('Select') }}
                                                            </option>
                                                            <option v-for="(item, itemIndex) in productNameList"
                                                                :key="itemIndex" :value="item.Value">{{ item.Text }}
                                                            </option>
                                                        </select>
                                                        <span v-if="errors[0]" name="ProductName"
                                                            class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                    </Field>

                                                </div>
                                            </div>
                                        </div>
                                        <div class="col-md-6">
                                            <label>{{ $t('SelectItem') }}:<span class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="Products" :rules="{ 'required': true }" label="ItemName"
                                                    v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="Products" id="Products" type="text"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="productUniqueName" value="iselectVal" />

                                                        <a @click="itemListOnClick" class="btn float-left w-auto m-0"
                                                            href="javascript:;"
                                                            style="background-color: #fff;color: #303030;border-color: #abb5bf;border-left: none;"><em
                                                                class="dropdown-toggle float-right"></em></a>
                                                        <span v-if="errors[0]" name="Products"
                                                            class="invalid-feedback d-block">{{
                                                                errors[0] }}</span>

                                                        <div class="unique_dynamicdatalist">
                                                            <ul v-for="(item, index) in productItemNameList"
                                                                @click="setProductItemName(item)" style="z-index: auto;"
                                                                :key="index">
                                                                <li v-if="showProductDropdown"
                                                                    style="text-transform: capitalize;"
                                                                    :value="item.Value">{{ item.Name }}</li>
                                                            </ul>
                                                        </div>

                                                    </div>

                                                </Field>

                                            </div>
                                        </div>
                                    </div>
                                    <div class="row">
                                        <div class="col-md-6">
                                            <label>{{ $t('Assign Quantity') }}:<span
                                                    class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="AssignQuantity" :rules="{ 'required': false }"
                                                    label="ItemName" v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="receiptName" type="number"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="aproveQuantity" disabled="disabled" />

                                                    </div>
                                                    <span v-if="errors[0]" name="AssignQuantity"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>

                                            </div>
                                        </div>
                                        <div class="col-md-6">
                                            <label>{{ $t('AvailableQuantity') }}:<span class="text-danger">*</span></label>
                                            <div style="align-items: flex-start;">
                                                <Field name="AvailableQuantity" :rules="{ 'required': true }"
                                                    label="ItemName" v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <input name="receiptName" type="number"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="availableQuantity" disabled="disabled" />

                                                    </div>
                                                    <span v-if="errors[0]" name="AvailableQuantity"
                                                        class="invalid-feedback d-block">{{ errors[0] }}</span>
                                                </Field>
                                            </div>
                                        </div>
                                    </div>

                                    <div class="row">
                                        <div class="col-md-12">
                                            <label> {{ $t('Comment') }}:</label>
                                            <div style="align-items: flex-start;">
                                                <Field name="Products" :rules="{ 'required': false }" label="ItemName"
                                                    v-slot="{ errors }" style="width:85%">
                                                    <div class="input-group mb-3" style="position: relative;">
                                                        <textarea name="txtComment" id="txtComment"
                                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                            v-model="comment" maxlength="200"></textarea>
                                                    </div>
                                                </Field>

                                            </div>
                                        </div>
                                    </div>


                                </div>
                            </Form>
                        </div>
                        <!-- <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
                            <div class="form-group float-md-right mb-0">
                                <div class="search-btm-btn">

                                    <a class="btn btn-success formbtn  text-white mr-2" title="Save"
                                        style="cursor: pointer;" id="btnSaveTerms" @click="Save"><em
                                            class="fa fa-save pr-2"></em>{{ $t('Save') }}</a>
                                    <a class="btn btn-danger formbtn text-white" title="Cancel" style="cursor: pointer;"
                                        @click="ClosePOP"><em class="fa fa-close pr-2"></em>{{
                                            $t('Cancel') }}</a>
                                </div>
                            </div>
                        </div> -->

                        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
                          <div class="row flex-row-reverse">
                          <div class="col-sm-12 col-md-6 col-lg-6 text-right">
                            <a class="btn btn-success formbtn text-white mr-2" title="Save" style="cursor: pointer;" id="btnSaveTerms" @click="Save">
                                <em class="fa fa-save pr-2"></em>{{ $t('Save') }}</a>
                            <a class="btn btn-danger formbtn text-white" title="Cancel" style="cursor: pointer;"  @click="ClosePOP">
                                <em class="fa fa-close pr-2"></em>{{ $t('Cancel') }}</a>
                          </div>
                          <div class="col-sm-12 col-md-6 col-lg-6">
                           <div class="py-2 mandatory">{{ $t('MandatoryString') }}</div>
                           </div>  
                          </div>
                        </div>


                    </div>
                </div>
            </div>
        </div>
    </div>

</template>
<script>
import DataService from '../../service/DataService'
export default {
    props: {
        ApprovedData: {
            type: Object,
            required: true,
        }
    },
    data() {
        return {
            isLoading: false,
            productTypeList: [],
            productNameList: [],
            productItemNameList: [],
            txtProductType: '',
            txtProductName: 0,
            productUniqueName: '',
            showProductDropdown: false,
            UserId: 0,
            productUniqueId: 0,
            receiptName: this.ApprovedData.ISSNUE_TO_NAME,
            aproveQuantity: this.ApprovedData.NUMBER_OF_ITEMS,
            availableQuantity: this.ApprovedData.AVAILABLE_QUANTITY,
            oldserialNumber: this.ApprovedData.serial_number ? null : 'N/A',
            replacementStatusName: this.ApprovedData.REPLACEMENT_TYPE_STATUS,
            comment: '',
            dataArray: [],
            searchProductData: [],
            preUniqueName: this.ApprovedData.UNIQUE_NAME,
            isunique: null,
        }
    },
    created() {

        var vm = this;
        var UserInfo = vm.GetUserInfo;
        vm.UserId = UserInfo.ID;
        vm.TreeValue = vm.ApprovedData.location_id;
        vm.txtProductType = vm.ApprovedData.asset_type_id;
        vm.getProductTypeList();
    },
    methods: {
        getProductTypeList: function () {

            var vm = this;
            vm.isLoading = true;
            vm.productNameList = []
            vm.productUniqueName = '';
            var url = `type=&issueTo=${this.UserId}&locationId=${this.TreeValue}&requestType=&requestFrom=assetrequisition`;
            DataService.AssignGetAssetType(url).then(response => {
                vm.isLoading = true;
                vm.productTypeList = response.data;
                if (vm.productTypeList.length > 0) {
                    // vm.txtProductType = vm.productTypeList[0].ASSETID;
                    vm.getProductNameList(vm.txtProductType);
                }
                else {
                    vm.productTypeList = []
                }

            });

        },

        getProductNameList(event) {
            var vm = this;
            if (event == "") {
                vm.productNameList = [];
                return;
            }
            vm.productItemNameList = []
            vm.productUniqueName = '';
            vm.productUniqueId = '';
            vm.availableQuantity = ''
            vm.showProductDropdown = false
            vm.isLoading = true;

            if (vm.ApprovedData.IS_UNIQUE) {
                vm.isunique = 'yes'
            }
            else {
                vm.isunique = 'no'
            }
            var url = `id=${vm.txtProductType}&isView=&barcode=&assetType=&assetUniqueId=&selfCheckout=&reqFrom=assetrequisition&isFor=&isuniqueSearch=&issueTo=${vm.UserId}&assignedFrom=&assignedTill=&startTime=&endTime=&locationId=${vm.TreeValue}&RFID=&pageSize=&pageNum=&assignedFromDateTime=&assignedTillDateTime=&uniqueIds=&catalogueIds=&isUnique=${vm.isunique}`;
            console.log("url", url);
            DataService.GetCompanyAssestCatalogsDetalis(url).then(response => {

                if (response.data.Result.length > 0) {
                    vm.productNameList = response.data.Result;
                    vm.isLoading = false;
                }
                else {
                    vm.productNameList = []
                    vm.isLoading = false;
                }

            });

        },


        searchByProduct() {
            var vm = this;
            vm.isLoading = true;
            vm.productUniqueId = '';
            vm.availableQuantity = ''
            vm.productUniqueName = '';
            if (vm.txtProductName == 0) {

                vm.showProductDropdown = false
                vm.isLoading = false;
                return;
            }
            // vm.$refs.product.validate().then(result => {
            //     if (result) {

            let currentDate = new Date();
            let today = new Date()
            let currentTime = new Date();
            today.setDate(currentDate.getDate() + 1);
            currentDate = vm.$options.filters.formatDateYear(currentDate);
            var endDate = vm.$options.filters.formatDateYear(today);
            var startTime = vm.$options.filters.formatTimee(currentTime);
            var endTime = vm.$options.filters.formatTimee('12:00 AM');
            var url = `id=${vm.txtProductType}&isView=1&barcode=&assetType=${vm.txtProductType}&assetUniqueId=${vm.productUniqueId != null ? vm.productUniqueId : ''}&selfCheckout=&reqFrom=assetrequisition&isFor=&isuniqueSearch=&issueTo=${vm.UserId}&assignedFrom=${currentDate}&assignedTill=${endDate}&locationId=${vm.TreeValue}&RFID=&pageSize=&pageNum=&assignedFromDateTime=&assignedTillDateTime=&startTime=${startTime}&endTime=${endTime}&uniqueIds=${vm.productUniqueId != null ? vm.productUniqueId : ''}&catalogueIds=${vm.txtProductName}`;

            DataService.GetCompanyAssestCatalogsDetalis(url).then(response => {
                if (response.data.length > 0) {
                    vm.searchProductData = response.data;
                    vm.availableQuantity = vm.searchProductData[0].AvailableItems;
                    vm.searchProductData.forEach(ele => {
                        ele.IsChecked = false;
                        ele.ReqQty = '';
                    })

                    //-------------------select Item list which has AvailableItems more than zero -------------------

                    const result = vm.searchProductData.filter(item => item.AvailableItems > 0)
                        .map(item => ({
                            Name: item.Name,
                            Value: item.ParentUniqueId,
                            AvailableItems: item.AvailableItems
                        }));
                    vm.productItemNameList = result;
                    //--------------------------------------
                    //------------filter if the item is already assigned------------------

                    if (vm.ApprovedData.IS_UNIQUE) {
                        const filteredArray = vm.productItemNameList.filter(item => item.Value !== vm.ApprovedData.RELATED_INFO_ID);
                        // console.log(result);
                        // console.log("filteredArray", filteredArray);
                        vm.productItemNameList = filteredArray;
                    }
                    //--------------------------------------
                    vm.NoRecordfound = false;

                    setTimeout(function () {
                        vm.CheckBoxBootstrap();
                    }, 100);
                    vm.isLoading = false;
                }
                else {
                    vm.NoRecordfound = true;
                    vm.searchProductData = []
                    vm.isLoading = false;
                }
            });
            //}
            // else {
            //     vm.isLoading = false;
            // }

            //})

        },
        // getProductItemNameList: function () {
        //     var vm = this;
        //     vm.isLoading = true;
        //     vm.productUniqueName = '';
        //     vm.productUniqueId = '';
        //     vm.showProductDropdown = false
        //     var url = `assetCatalogId=${this.txtProductName}&name=&issueTo=${this.UserId}&locationId=${this.TreeValue}&requestFrom=assetrequisition&assetType=`;
        //     DataService.GetUniqueAssetItems(url).then(response => {
        //         if (response.data.length > 0) {
        //             vm.isLoading = false;
        //             vm.productItemNameList = response.data;
        //             vm.availableQuantity = ''
        //         }
        //         else {
        //             vm.isLoading = false;
        //             vm.productItemNameList = []
        //         }
        //     });
        // },

        setProductItemName: function (item) {
            var vm = this;
            vm.productUniqueId = item.Value;
            vm.productUniqueName = item.Name;
            vm.showProductDropdown = false;
            vm.availableQuantity = item.AvailableItems;
        },
        ClosePOP: function (item) {

            this.$emit('ClosePopUp', item);
        },
        itemListOnClick: function () {
            if (this.showProductDropdown == false) {
                this.showProductDropdown = true
            }
            else {
                this.showProductDropdown = false
            }
        },
        Save() {
            var vm = this;
            vm.isLoading = true;

            if (vm.availableQuantity == 0) {
                vm.isLoading = false;
                return vm.ShowAlert(vm.$t("Available quantity is 0"), "warning", vm.$t("Alert"));
            }
            if (vm.aproveQuantity > vm.availableQuantity) {
                vm.isLoading = false;
                return vm.ShowAlert(vm.$t("Available quantity is less than requested quantity"), "warning", vm.$t("Alert"));
            }

            vm.$refs.product.validate().then(result => {
                if (result) {
                    var formData = new FormData();
                    var itemnames = `${vm.ApprovedData.NAME}(${vm.ApprovedData.ITEM_CODE})`
                    var obj = {
                        "AssetCatalogUniqueId": parseInt(vm.productUniqueId) > 0 ? parseInt(vm.productUniqueId) : 0,
                        "RequestFromRequsition": 1,
                        "IsGroup": null,
                        "ParentAssetCatalogUniqueId": parseInt(vm.txtProductName),
                        "AssetQuantity": vm.ApprovedData.NUMBER_OF_ITEMS,
                        "RequestQuantity": vm.ApprovedData.NUMBER_OF_ITEMS,
                        "BatchId": null,
                        "AssetUniqueName": itemnames
                    }
                    vm.dataArray.push(obj);

                    var mainObj = {
                        UserId: vm.ApprovedData.issued_to,
                        DepartmentId: 0,
                        AssignedFrom: null,
                        AssignedTill: null,
                        AssignedFromDateTime: vm.$options.filters.formatDateTimeYYMMDD(vm.ApprovedData.assigned_from),
                        AssignedTillDateTime: vm.$options.filters.formatDateTimeYYMMDD(vm.ApprovedData.assigned_till),
                        StartTime: null,
                        EndTime: null,
                        Comment: vm.comment,
                        NotificationUsers: vm.ApprovedData.issued_to,
                        RequestFrom: 'AssetAssign',
                        IsRequestFromRequisition: false,
                        IssueToName: vm.ApprovedData.ISSNUE_TO_NAME,
                        RFID: 0,
                        GroupRequistionAssestInfostring: vm.dataArray,
                        itemNames: itemnames,
                        ParentAssetAssignmentId: vm.ApprovedData.ASSET_ASSIGNMENT_ID,
                        ReceiptName: vm.receiptName,
                    };
                    formData.append("file", null);
                    formData.append("fileName", null);
                    formData.append("postString", JSON.stringify(mainObj));

                    // if(vm.ApprovedData.AVAILABLE_QUANTITY>=vm.ApprovedData.NUMBER_OF_ITEMS){

                    DataService.SaveGroupAssign(formData).then(response => {
                        if (response.data.status == 0) {
                            if (response.data.existIds == '') {
                                vm.ShowAlert(vm.$t("Itemassignedsuccessfully"), "success", vm.$t('Alert'));
                                vm.isLoading = false;
                                vm.ShowAlert(vm.$t("Replaced successfully"), "success", vm.$t('Alert'));
                                vm.$emit('ClosePopUp');
                                vm.$emit('RefreshData');
                            }
                        }
                        else {
                            vm.isLoading = false;
                            vm.ShowAlert(vm.$t("Something went wrong "), "warning", vm.$t('Alert'));
                        }
                    })
                    // }

                    // else{
                    //     vm.isLoading = false;
                    //     return vm.ShowAlert(vm.$t("Requested quantity not available. "), "warning", vm.$t("Alert"));
                    // }

                }
                else {
                    vm.isLoading = false;
                    vm.ShowAlert(vm.$t("Please Correct the Highlighted errors"), "warning", vm.$t('Alert'));
                }
            })
        },

    }
}
</script>